# Let me look at this from a different perspective:
# The output appears to be a diagonally shifted version of the input
# Let's see if Output[r] relates to Input[r-k] for some k

print("Checking Output[r] vs Input[r-k] for various k:")
for r in range(8):
    for k in range(1, 9):
        shift_right_1 = True
        match = None

        if shift_right_1:
            # Output[r] = Input[r-k] shifted right by 1
            prev_row = input_demo[(r-k) % 8]
            if prev_row is None:
                match = False
                break
            shifted_cols = set()
            for c in range(20):
                if prev_row[c] == 5:
                    shifted_cols.add((c+1) % 21)
            output_cols = set(c for c in range(21) if output_demo[r][c] == 5)
            match = shifted_cols == output_cols
        else:
            # Output[r] = Input[r-k]
            prev_row = input_demo[(r-k) % 8]
            input_cols = set(c for c in range(21) if prev_row[c] == 5)
            output_cols = set(c for c in range(21) if output_demo[r][c] == 5)
            match = input_cols == output_cols
            if match:
                print(f"r={r}: Found Input[{(r-k)%8}] directly matches Output[{r}]")
                break

